<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
import {systemApi,type SystemConfig,type SystemConfigValues} from '@/services/api';
import ConnectionSettingsPanel from './ConnectionSettingsPanel.vue';
const tab=ref('base');
const config=ref<SystemConfig|null>(null),busy=ref(''),error=ref(''),message=ref('');
const port=ref(''),host=ref(''),prefix=ref(''),origin=ref(''),origins=ref('');
function fill(v:SystemConfig){config.value=v;const i=v.saved.listen.lastIndexOf(':');host.value=v.saved.listen.slice(0,i);port.value=v.saved.listen.slice(i+1);prefix.value=v.saved.adminPath.replace(/^\//,'');origin.value=v.saved.publicOrigin;origins.value=(v.saved.clientOrigins||[]).join('\n');}
const dirty=computed(()=>{if(!config.value)return false;const s=config.value.saved;return host.value+':'+port.value!==s.listen||'/'+prefix.value!==s.adminPath||origin.value!==s.publicOrigin||origins.value!==(s.clientOrigins||[]).join('\n');});
async function load(){if(dirty.value&&!window.confirm('重新读取会替换尚未保存的输入，是否继续？'))return;busy.value='load';error.value='';try{fill(await systemApi.config());}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
async function save(section:string){if(busy.value)return;busy.value=section;error.value='';message.value='';try{let input:Partial<SystemConfigValues>={};if(section==='listen')input={listen:host.value+':'+port.value};if(section==='entry')input={adminPath:'/'+prefix.value};if(section==='origin')input={publicOrigin:origin.value.trim(),clientOrigins:origins.value.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean)};const v=await systemApi.saveConfig(input);config.value=v;message.value=v.restartRequired?'本区配置已写入服务器，重启服务后生效。其他区未保存的输入仍保留。':'本区配置已保存，与当前运行值一致。';}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
function copy(data:string){uni.setClipboardData({data});}
onMounted(load);
</script>
<template><view class="service-settings"><view class="page-head"><view><text class="eyebrow">SYSTEM / CONFIGURATION</text><h2>服务配置</h2><text class="muted">管理服务入口、数据库与 Redis。配置直接读写当前服务器。</text></view><text class="badge">服务器配置</text></view>
<view class="tabs" role="tablist" aria-label="服务配置分类"><button v-for="t in [{id:'base',name:'基础服务'},{id:'connections',name:'连接配置'}]" :key="t.id" role="tab" :aria-selected="tab===t.id" :class="{selected:tab===t.id}" @click="tab=t.id">{{t.name}}</button></view>
<view v-show="tab==='base'"><view class="status-bar"><text><text class="status-dot" :class="{pending:config?.restartRequired}"></text>{{config?(config.restartRequired?'有配置等待重启生效':'配置与运行状态一致'):(busy?'正在读取服务器配置':'配置尚未读取')}}<text v-if="dirty"> · 有未保存输入</text></text><button :disabled="!!busy" @click="load">{{busy==='load'?'读取中…':'重新读取'}}</button></view>
<text v-if="error" class="notice error" role="alert">{{error}}</text><text v-if="message" class="notice" role="status">{{message}}</text><text v-if="config?.restartRequired" class="notice pending-note">已保存值待重启生效。请在宝塔进程管理中重启运营服务；修改端口时同步调整反向代理，修改入口后使用新入口进入。</text>
<template v-if="config"> <view class="config-card"><view class="card-head"><view class="head-title"><text>服务监听</text><text class="badge">重启生效</text></view><button class="primary" :disabled="!!busy||!config.writable" @click="save('listen')">{{busy==='listen'?'保存中…':'保存'}}</button></view>
 <view class="card-body"><view class="field-row"><text class="field-label">监听端口</text><view class="field-content"><input v-model="port" :disabled="!!busy" type="number" placeholder="1–65535" aria-label="监听端口"/><text class="help">运营服务接收请求的端口，范围 1–65535。</text></view></view>
 <view class="field-row"><text class="field-label">监听范围</text><view class="field-content"><view class="segments"><button :disabled="!!busy" :class="{selected:host==='127.0.0.1'}" @click="host='127.0.0.1'">仅本机</button><button :disabled="!!busy" :class="{selected:host==='0.0.0.0'}" @click="host='0.0.0.0'">全部网卡</button></view><text class="help">宝塔 Nginx 反向代理部署使用“仅本机”；直接通过端口访问使用“全部网卡”。</text><details><summary>指定监听地址</summary><input v-model="host" :disabled="!!busy" placeholder="127.0.0.1 或 [::1]" aria-label="指定监听地址"/></details></view></view><view class="active-row"><text>当前运行</text><text selectable>{{config.active.listen}}</text><text v-if="config.saved.listen!==config.active.listen" class="pending-value">待生效 {{config.saved.listen}}</text></view></view></view>
 <view class="config-card"><view class="card-head"><view class="head-title"><text>后台入口</text><text class="badge">重启生效</text></view><button class="primary" :disabled="!!busy||!config.writable" @click="save('entry')">{{busy==='entry'?'保存中…':'保存'}}</button></view><view class="card-body"><view class="field-row"><text class="field-label">访问后缀</text><view class="field-content"><view class="prefix-input"><text>/</text><input v-model="prefix" :disabled="!!busy" :maxlength="6" placeholder="例如 a034ef" aria-label="后台访问后缀"/></view><text class="help">固定 6 位，使用小写 a–f 和数字。保存后记录新入口，重启才切换。</text></view></view><view class="active-row"><text>当前入口</text><text selectable>{{config.active.publicOrigin}}{{config.active.adminPath}}</text><button @click="copy(config.active.publicOrigin+config.active.adminPath)">复制</button></view><view v-if="config.saved.adminPath!==config.active.adminPath" class="active-row"><text>重启后入口</text><text selectable>{{config.saved.publicOrigin}}{{config.saved.adminPath}}</text></view></view></view>
 <view class="config-card"><view class="card-head"><view class="head-title"><text>公开地址与网页接入</text><text class="badge">重启生效</text></view><button class="primary" :disabled="!!busy||!config.writable" @click="save('origin')">{{busy==='origin'?'保存中…':'保存'}}</button></view><view class="card-body"><view class="field-row"><text class="field-label">公开服务地址</text><view class="field-content"><input v-model="origin" :disabled="!!busy" placeholder="https://你的运营服务域名" aria-label="公开服务地址"/><text class="help">填写纯域名来源，不含路径或尾斜线。App 主备域名和打包器链接在“App 接口与域名”管理。</text></view></view><view class="field-row"><text class="field-label">网页来源白名单</text><view class="field-content"><textarea v-model="origins" :disabled="!!busy" :maxlength="-1" placeholder="每行一个 HTTPS 网页来源；没有跨域网页可留空" aria-label="网页来源白名单"/><text class="help">用于网页跨域访问，最多 32 项；安卓、iOS 原生请求无需填在这里。</text></view></view><view class="active-row"><text>当前公开地址</text><text selectable>{{config.active.publicOrigin}}</text></view></view></view>
 <details><summary>运行目录与服务身份 · 只读信息</summary><view class="detail-grid"><view class="config-card"><view class="card-head"><view class="head-title"><text>日志与存储</text></view><text class="badge">实际运行信息</text></view><view class="card-body"><view class="read-only-row"><text>存储方式</text><strong>{{config.storage==='mysql'?'MySQL 数据库':'本机文件 · 预览模式'}}</strong></view><view class="read-only-row"><text>数据目录</text><text class="small-code" selectable>{{config.dataDir}}</text></view><view class="read-only-row"><text>操作审计文件</text><text class="small-code" selectable>{{config.auditPath}}</text></view><text class="help">操作审计写入当前数据目录，可在“日志查看”读取与下载。进程运行日志在宝塔进程管理中查看。</text></view></view>
 <view class="config-card"><view class="card-head"><view class="head-title"><text>接入身份</text></view><text class="badge">已启用签名验证</text></view><view class="card-body"><view class="read-only-row"><text>签名算法</text><strong>{{config.identity.algorithm}}</strong></view><view class="read-only-row"><text>服务公钥指纹 · SHA-256</text><text class="small-code fingerprint" selectable>{{config.identity.fingerprint}}</text></view><view class="inline-actions"><button @click="copy(config.identity.fingerprint)">复制指纹</button></view><text class="help">打包器校验签名目录与服务身份。身份由本机密钥生成并持久保存，管理员密码与私钥不会放入接入链接。</text></view></view></view>
</details> <text v-if="!config.writable" class="notice error">当前实例没有可写配置文件，无法保存设置。</text>
 </template></view><ConnectionSettingsPanel v-show="tab==='connections'"/></view></template>
<style scoped src="../styles/service-forms.css"></style>
